:root {
  --ink-dark: #1c1810;
  --ink-mid: #3a2e1a;
  --parchment: #e8dfc8;
  --parchment-light: #f2ead8;
  --parchment-mid: #d9cdb0;
  --deep-teal: #1d4a52;
  --deep-teal-light: #2a6670;
  --rust: #8b3a2a;
  --rust-light: #c05a3a;
  --gold: #b8860b;
  --gold-light: #d4a017;
  --slate-blue: #2e3f5c;
  --sage: #4a6741;
  --meter-bg: #c4b898;
  --oxygen-fill: #3a7a5a;
  --pressure-fill: #8b3a2a;
  --temp-fill: #2e5c8a;
  --vis-fill: #6a5a2a;
}

article.dive-log {
  width: 480px;
  background-color: var(--parchment);
  border: 3px solid var(--ink-mid);
  border-radius: 4px;
  font-size: 13px;
  color: var(--ink-dark);
  overflow: hidden;
}

.log-header {
  background-color: var(--deep-teal);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-bottom: 3px solid var(--gold);
}

.vessel-badge {
  width: 42px;
  height: 42px;
  background-color: var(--gold);
  color: var(--deep-teal);
  font-size: 13px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  border: 2px solid var(--parchment);
  flex-shrink: 0;
  letter-spacing: 1px;
}

.header-text {
  flex: 1;
}

.log-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--parchment-light);
  margin: 0 0 2px 0;
  letter-spacing: 0.5px;
  line-height: 1.1;
}

.log-subtitle {
  font-size: 10px;
  color: var(--parchment-mid);
  margin: 0;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}

.depth-gauge {
  display: flex;
  flex-direction: column;
  align-items: center;
  background-color: var(--slate-blue);
  border: 2px solid var(--gold-light);
  border-radius: 4px;
  padding: 4px 10px;
}

.gauge-value {
  font-size: 18px;
  font-weight: 800;
  color: var(--gold-light);
  line-height: 1;
}

.gauge-unit {
  font-size: 9px;
  color: var(--parchment-mid);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.log-body {
  display: flex;
  gap: 0;
}

.dive-meta {
  width: 168px;
  padding: 10px 12px;
  border-right: 2px dashed var(--parchment-mid);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.meta-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  border-bottom: 1px dotted var(--parchment-mid);
  padding-bottom: 4px;
}

.meta-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--ink-mid);
  font-weight: 600;
}

.meta-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--deep-teal);
}

.readings-panel {
  flex: 1;
  padding: 10px 12px;
}

.readings-title {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--rust);
  font-weight: 700;
  margin: 0 0 8px 0;
  border-bottom: 1px solid var(--rust-light);
  padding-bottom: 4px;
}

.readings-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 10px;
}

.reading-cell {
  display: flex;
  align-items: center;
  gap: 5px;
}

.reading-label {
  font-size: 10px;
  color: var(--ink-mid);
  font-weight: 600;
  width: 56px;
  flex-shrink: 0;
}

.reading-bar {
  flex: 1;
  height: 8px;
  background-color: var(--meter-bg);
  border-radius: 2px;
  overflow: hidden;
  border: 1px solid var(--parchment-mid);
}

.reading-fill {
  height: 100%;
  border-radius: 2px;
}

.fill-oxygen {
  width: 74%;
  background-color: var(--oxygen-fill);
}

.fill-pressure {
  width: 91%;
  background-color: var(--pressure-fill);
}

.fill-temp {
  width: 38%;
  background-color: var(--temp-fill);
}

.fill-vis {
  width: 22%;
  background-color: var(--vis-fill);
}

.reading-pct {
  font-size: 10px;
  font-weight: 700;
  color: var(--ink-dark);
  width: 24px;
  text-align: right;
  flex-shrink: 0;
}

.log-footer {
  background-color: var(--parchment-mid);
  border-top: 2px solid var(--ink-mid);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 14px;
}

.observation-tags {
  display: flex;
  gap: 5px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.obs-tag {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  padding: 2px 7px;
  border-radius: 10px;
  border: 1px solid transparent;
}

.tag-bio {
  background-color: var(--deep-teal);
  color: var(--parchment-light);
  border-color: var(--deep-teal-light);
}

.tag-fauna {
  background-color: var(--sage);
  color: var(--parchment-light);
  border-color: var(--sage);
}

.tag-current {
  background-color: var(--slate-blue);
  color: var(--parchment-light);
  border-color: var(--slate-blue);
}

.status-stamp {
  font-size: 11px;
  font-weight: 800;
  color: var(--rust);
  border: 2px solid var(--rust);
  padding: 3px 10px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  transform: rotate(-1.5deg);
}
